   "js": "(() => {\n  // Colours are read from these tokens, so the background follows any theme.\n  const TOKENS = [\"--ds-bg\",\"--ds-surface\",\"--ds-line\",\"--ds-ink\",\"--ds-info-line\"];\n  const RES = 0.6;\n  const STILL_TIME = 12;\n  const VERT = 'attribute vec2 p; void main() { gl_Position = vec4(p, 0.0, 1.0); }';\n  const FRAG = `\n#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\nuniform vec2 uRes;\nuniform float uTime;\nuniform vec3 uC[5];\nuniform float uAmt;\n\nfloat h21(vec2 p) { return fract(sin(dot(p, vec2(41.37, 289.91))) * 9371.3); }\nfloat vn(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);\n}\nfloat fbm(vec2 p) {\n  float a = 0.5, s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vn(p); p = p * 2.03 + vec2(11.7, 5.3); a *= 0.5; }\n  return s;\n}\nfloat fbmL(vec2 p) {\n  float a = 0.5, s = 0.0;\n  for (int i = 0; i < 3; i++) { s += a * vn(p); p = p * 2.03 + vec2(11.7, 5.3); a *= 0.5; }\n  return s;\n}\n\nvoid main() {\n  vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / sqrt(uRes.x * uRes.y);\n  float t = uTime * 0.035;\n  vec2 p = uv * 2.0;\n  float w = fbm(p * 1.3 + vec2(t, -t * 0.7));\n  float w2 = fbm(p * 2.6 - w * 1.6 + t);\n  float v1 = sin((p.x * 1.2 + p.y * 0.7) * 3.0 + w * 7.5 + w2 * 3.0);\n  float vein1 = pow(1.0 - smoothstep(0.0, 0.42, abs(v1)), 2.2);\n  float v2 = sin((p.x * 0.6 - p.y * 1.1) * 4.5 + w2 * 9.0 + w * 2.0);\n  float vein2 = 1.0 - smoothstep(0.0, 0.14, abs(v2));\n  vec3 col = mix(uC[0], uC[1], 0.35 + 0.5 * fbm(p * 0.9 + 4.0));\n  col = mix(col, uC[2], smoothstep(0.35, 0.85, w2) * 0.55);\n  col = mix(col, uC[3], vein1 * 0.2 + vein2 * 0.06);\n  col = mix(col, uC[4], vein1 * smoothstep(0.55, 0.9, w) * 0.10);\n  gl_FragColor = vec4(mix(uC[0], col, uAmt), 1.0);\n}\n`;\n\n  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  const swatch = document.createElement('canvas');\n  swatch.width = swatch.height = 1;\n  const sctx = swatch.getContext('2d', { willReadFrequently: true });\n\n  // Resolve any CSS colour (hex, rgb, oklch, color-mix) to sRGB floats through a 1px canvas.\n  function readColours(probe) {\n    const out = [];\n    for (const name of TOKENS) {\n      probe.style.color = 'var(' + name + ')';\n      sctx.clearRect(0, 0, 1, 1);\n      sctx.fillStyle = '#000';\n      sctx.fillStyle = getComputedStyle(probe).color;\n      sctx.fillRect(0, 0, 1, 1);\n      const d = sctx.getImageData(0, 0, 1, 1).data;\n      out.push(d[0] / 255, d[1] / 255, d[2] / 255);\n    }\n    return out;\n  }\n\n  function shader(gl, type, src) {\n    const s = gl.createShader(type);\n    gl.shaderSource(s, src);\n    gl.compileShader(s);\n    return gl.getShaderParameter(s, gl.COMPILE_STATUS) ? s : null;\n  }\n\n  function init(root) {\n    if (root.dataset.okInit) return;\n    root.dataset.okInit = '1';\n    const canvas = root.querySelector('.canvas');\n    const probe = root.querySelector('.probe');\n    const gl = canvas.getContext('webgl', { antialias: false, alpha: false, powerPreference: 'low-power' });\n    if (!gl) return;\n    const vs = shader(gl, gl.VERTEX_SHADER, VERT);\n    const fs = shader(gl, gl.FRAGMENT_SHADER, FRAG);\n    if (!vs || !fs) return;\n    const prog = gl.createProgram();\n    gl.attachShader(prog, vs);\n    gl.attachShader(prog, fs);\n    gl.linkProgram(prog);\n    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return;\n    gl.useProgram(prog);\n    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());\n    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);\n    const loc = gl.getAttribLocation(prog, 'p');\n    gl.enableVertexAttribArray(loc);\n    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);\n    const uRes = gl.getUniformLocation(prog, 'uRes');\n    const uTime = gl.getUniformLocation(prog, 'uTime');\n    const uC = gl.getUniformLocation(prog, 'uC');\n    const uAmt = gl.getUniformLocation(prog, 'uAmt');\n\n    let t = reduced ? STILL_TIME : 0;\n    let last = 0;\n    let raf = 0;\n    let visible = false;\n    let key = '';\n\n    const draw = () => {\n      gl.uniform1f(uTime, t);\n      gl.drawArrays(gl.TRIANGLES, 0, 3);\n    };\n    const size = () => {\n      const r = root.getBoundingClientRect();\n      const s = Math.min(window.devicePixelRatio || 1, 1.5) * RES;\n      const w = Math.max(2, Math.round(r.width * s));\n      const h = Math.max(2, Math.round(r.height * s));\n      if (canvas.width !== w || canvas.height !== h) {\n        canvas.width = w;\n        canvas.height = h;\n        gl.viewport(0, 0, w, h);\n        gl.uniform2f(uRes, w, h);\n        draw();\n      }\n    };\n    const refresh = () => {\n      if (!root.isConnected) { clearInterval(timer); return; }\n      const c = readColours(probe);\n      const k = c.join();\n      if (k === key) return;\n      key = k;\n      gl.uniform3fv(uC, new Float32Array(c));\n      // Dark grounds get a gentler tint so light text keeps its contrast.\n      gl.uniform1f(uAmt, 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2] < 0.4 ? 0.6 : 1.0);\n      draw();\n    };\n    const tick = (now) => {\n      raf = 0;\n      if (!visible || document.hidden) return;\n      t += Math.min(0.1, (now - last) / 1000);\n      last = now;\n      draw();\n      raf = requestAnimationFrame(tick);\n    };\n    const start = () => {\n      if (reduced || raf || !visible || document.hidden) return;\n      last = performance.now();\n      raf = requestAnimationFrame(tick);\n    };\n    const stop = () => { if (raf) cancelAnimationFrame(raf); raf = 0; };\n\n    canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); stop(); root.classList.remove('is-live'); });\n\n    const timer = setInterval(refresh, 2000);\n    refresh();\n    size();\n    root.classList.add('is-live');\n\n    new ResizeObserver(size).observe(root);\n    new IntersectionObserver((entries) => {\n      visible = entries[entries.length - 1].isIntersecting;\n      if (visible) start(); else stop();\n    }).observe(root);\n    document.addEventListener('visibilitychange', () => (document.hidden ? stop() : start()));\n  }\n\n  document.querySelectorAll('.c-marble').forEach(init);\n})();"
