   "js": "(() => {\n  const NS = 'http://www.w3.org/2000/svg';\n  const el = (tag, attrs, parent, text) => {\n    const e = document.createElementNS(NS, tag);\n    for (const k in attrs) e.setAttribute(k, attrs[k]);\n    if (text != null) e.textContent = text;\n    if (parent) parent.appendChild(e);\n    return e;\n  };\n  const check = (p, x, y, s, state) => {\n    const g = el('g', {}, p);\n    if (state === 'done' || state === 'fail') {\n      el('rect', { x: x - s / 2, y: y - s / 2, width: s, height: s, rx: s * 0.18, class: state === 'done' ? 'f-pass' : 'f-fail' }, g);\n      const d = state === 'done'\n        ? `M${x - s * 0.25} ${y} l${s * 0.17} ${s * 0.17} l${s * 0.33} ${-s * 0.33}`\n        : `M${x - s * 0.2} ${y - s * 0.2} L${x + s * 0.2} ${y + s * 0.2} M${x + s * 0.2} ${y - s * 0.2} L${x - s * 0.2} ${y + s * 0.2}`;\n      el('path', { d, class: 'f-none s-bg', 'stroke-width': s * 0.12, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, g);\n    } else {\n      el('rect', { x: x - s / 2, y: y - s / 2, width: s, height: s, rx: s * 0.18, class: 'f-bg ' + (state === 'bad' ? 's-fail' : 's-pass'), 'stroke-width': Math.max(1.5, s * 0.07) }, g);\n    }\n    return g;\n  };\n  const person = (p, x, y, r, tone) => {\n    tone = tone || 'human';\n    const g = el('g', {}, p);\n    el('circle', { cx: x, cy: y, r, class: 'f-bg s-' + tone, 'stroke-width': r * 0.12 }, g);\n    el('circle', { cx: x, cy: y - r * 0.2, r: r * 0.28, class: 'f-' + tone }, g);\n    el('path', { d: `M${x - r * 0.55} ${y + r * 0.62} a${r * 0.55} ${r * 0.5} 0 0 1 ${r * 1.1} 0`, class: 'f-' + tone }, g);\n    return g;\n  };\n  const spark = (p, x, y, r) => {\n    const g = el('g', { class: 's-path', 'stroke-width': r * 0.18, 'stroke-linecap': 'round' }, p);\n    for (let i = 0; i < 8; i++) {\n      const a = i * Math.PI / 4 + Math.PI / 8;\n      const l = i % 2 ? r * 0.72 : r;\n      el('line', { x1: x + Math.cos(a) * r * 0.2, y1: y + Math.sin(a) * r * 0.2, x2: x + Math.cos(a) * l, y2: y + Math.sin(a) * l }, g);\n    }\n    return g;\n  };\n  const chip = (p, x, y, verb, arg, o) => {\n    o = o || {};\n    const fs = o.fs || 20;\n    const pad = 10;\n    const w = (verb.length + (arg ? arg.length + 1 : 0) + (o.mark ? 2 : 0)) * fs * 0.6 + pad * 2;\n    const g = el('g', { class: 'mono' }, p);\n    el('rect', { x: x - w / 2, y: y - fs * 0.9, width: w, height: fs * 1.8, rx: 6, class: o.danger ? 'f-failfill s-fail' : 'f-raised s-line', 'stroke-width': 1 }, g);\n    const t = el('text', { x: x - w / 2 + pad, y: y + fs * 0.35, 'font-size': fs, class: o.danger ? 'f-fail' : 'f-ink' }, g, verb);\n    if (arg) el('tspan', { class: o.danger ? 'f-fail' : 'f-dim' }, t, ' ' + arg);\n    if (o.mark) el('tspan', { class: o.danger ? 'f-fail' : 'f-text' }, t, ' ' + o.mark);\n    return g;\n  };\n  const bubble = (p, x, y, txt, fs, anchor) => {\n    fs = fs || 22;\n    const w = txt.length * fs * 0.52 + 28;\n    const x0 = anchor === 'end' ? x - w : x;\n    el('rect', { x: x0, y: y - fs * 1.05, width: w, height: fs * 2, rx: 8, class: 'f-panel' }, p);\n    el('text', { x: x0 + 14, y: y + fs * 0.3, 'font-size': fs, class: 'f-ink' }, p, txt);\n  };\n  const wave = (x0, x1, yc, amp, waves) => {\n    let d = '';\n    for (let i = 0; i <= 160; i++) {\n      const t = i / 160;\n      const x = x0 + (x1 - x0) * t;\n      const y = yc - amp * Math.sin(Math.PI * Math.min(1, t * 1.05)) * Math.sin(t * Math.PI * 2 * waves);\n      d += (i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1);\n    }\n    return d;\n  };\n  const waveY = (x, x0, x1, yc, amp, waves) => {\n    const t = (x - x0) / (x1 - x0);\n    return yc - amp * Math.sin(Math.PI * Math.min(1, t * 1.05)) * Math.sin(t * Math.PI * 2 * waves);\n  };\n  const baseline = (p, x0, x1, y) => el('line', { x1: x0, y1: y, x2: x1, y2: y, class: 's-faint', 'stroke-width': 2, 'stroke-dasharray': '2 9', 'stroke-linecap': 'round' }, p);\n  const startNode = (p, x, y) => el('rect', { x: x - 7, y: y - 7, width: 14, height: 14, rx: 3, class: 'f-bg s-dim', 'stroke-width': 2 }, p);\n\n  document.querySelectorAll('.c-agent-guard-flow').forEach((root) => {\n    if (root.dataset.okInit) return;\n    root.dataset.okInit = '1';\n    const s = root.querySelector('svg');\n\n    const DATA = { call: ['Bash', 'git reset --hard', 'tool call'], rule: ['Deny rule', 'blocked'], later: ['Auto-approve', 'never sees it'] };\n    el('rect', { x: 140, y: 330, width: 400, height: 150, rx: 16, class: 'f-panel' }, s);\n    const t = el('text', { x: 340, y: 400, 'text-anchor': 'middle', 'font-size': 32, class: 'mono f-ink' }, s, DATA.call[0]);\n    el('tspan', { class: 'f-text' }, t, ' ' + DATA.call[1]);\n    el('text', { x: 340, y: 445, 'text-anchor': 'middle', 'font-size': 24, class: 'f-dim' }, s, DATA.call[2]);\n    el('path', { d: 'M555 405 H640 M626 392 L642 405 L626 418', class: 'f-none s-fail', 'stroke-width': 3 }, s);\n    el('rect', { x: 660, y: 330, width: 320, height: 150, rx: 16, class: 'f-failfill s-fail', 'stroke-width': 2 }, s);\n    el('text', { x: 820, y: 400, 'text-anchor': 'middle', 'font-size': 34, class: 'f-ink' }, s, DATA.rule[0]);\n    el('text', { x: 820, y: 445, 'text-anchor': 'middle', 'font-size': 24, class: 'f-fail' }, s, DATA.rule[1]);\n    el('path', { d: 'M1000 405 H1100', class: 's-faint', 'stroke-width': 3, 'stroke-dasharray': '2 8', 'stroke-linecap': 'round' }, s);\n    el('rect', { x: 1120, y: 330, width: 340, height: 150, rx: 16, class: 'f-none s-line', 'stroke-width': 2 }, s);\n    el('text', { x: 1290, y: 400, 'text-anchor': 'middle', 'font-size': 34, class: 'f-dim' }, s, DATA.later[0]);\n    el('text', { x: 1290, y: 445, 'text-anchor': 'middle', 'font-size': 24, class: 'f-faint' }, s, DATA.later[1]);\n\n  });\n})();"
